    '<p>你轉頭看牆上的紅字。五行規則，讀了一遍。</p>',
    '<p>阿凱也在看。看得太快。幾秒掃完，轉過頭對你笑。</p>',
    '<p>第一次踏入門後的人，看見「打開即死」，不該是這個表情。</p>',
    '<p>你把這念頭壓下去。還不能定。</p>',
