        '<p>他回過頭。臉還是那張老趙的臉，輪廓卻開始發虛、發亮。<span class="dialogue">你什麼時候發現的？</span>開口的是他的嘴，出來的聲音卻疊著好幾個人。</p>',
        '<p><span class="dialogue">從一開始。</span>你說，<span class="dialogue">你看規則太快。燈滅三秒，你全安靜。每次最危險的那個選項，永遠是你先開口。</span></p>',
