  onEnter(){state.flags.alone_escape=true;setTimeout(()=>triggerEnding('survive_hide','倖存者','你躲在3號房等到天亮。門扉強制開啟，你活下來了。但你什麼都沒解決——旅館的秘密、鏡像的真相、出口的位置，全是謎。你帶著這些謎回到回廊。','逃過一劫 #1'),800)},
  choices:[]
