    '<p>阿凱的笑沒了。身子開始變透明——邊緣發白，五官模糊。</p>',
    '<p>你發現了。聲音變了，不再是少年的嗓音，沒錯，我是鏡像。這扇門扉的規則生出來的。我的任務是說假話，把你們往死路上帶。</p>',
    '<p>可我不想死。這扇門一關閉，鏡像就會被消掉。你們要肯帶我走，我可以給你們情報。</p>',
    '<p>老趙後退一步，拳頭攥緊。蘇晚的手伸進口袋。</p>'
