    '<p>你睜眼。閱覽區只剩你。長桌上還放著陳姐的保溫杯。沙發上還有小宇的眼鏡。牆角，老周那把螺絲刀。</p>',
    '<p>人，都沒了。</p>',
    '<p>你坐著，很久沒動。</p>',
    '<p>第三次鈴響了。這次不一樣。更輕，更遠，像從很遠的地方傳來。</p>',
    '<p>大廳的門開了。門外是回廊的白。</p>',
