    '<p>鐵門還開著。你拉開過的冷凍抽屜，有一關不嚴，露出一條縫。</p>',
    '<p>那個戴口罩的模特還躺在第四格。胸前的名牌寫著「周敏」。你已經知道她是誰了。</p>',
    '<p>盡頭桌上的登記簿翻開著。十四個無名件。你不想再翻第二遍。</p>'
