  onEnter:()=>{state.flags.elevator_used=true;loseTime(5)},
  choices:[
    {text:'推開「記憶核心區」的門',next:'basement'},
    {text:'在走廊裡最後準備一下',next:'basement_entrance'},
    {text:'坐電梯回五樓',next:'director_office'}
  ]
