/* ===== 18. 夜巡護士遭遇 ===== */
SCENES.night_nurse_encounter={
  room:'走廊',roomName:'夜巡護士',sceneId:'遭遇',mood:'terror',
  text:[
    '<p>你聽到了。</p>',
    '<p>很輕的腳步聲。「噠、噠、噠。」高跟鞋。踩在瓷磚地上。越來越近。</p>',
    '<p>你轉過身。</p>',
    '<p>[ghost][ghost]她站在走廊的盡頭。白色護士服。口罩。眼睛是純黑的——沒有眼白。手裡拿著一支注射器。針頭很長，在燈光下反了一下光。</p>',
    '<p class="dialogue">噓——她說。聲音很輕，很長，像風吹過鑰匙孔。</p>',
    '<p>她看到你了。她開始走過來。不快。但不停。</p>',
    '<p>你的心跳在耳朵裡響。</p>',
    '<p class="action">你只有幾秒鐘。</p>'
  ],
  onEnter:()=>{loseTime(5)},
  choices:[
    {text:'轉身就跑',next:'night_nurse_run',danger:true,personality:{cautious:+5}},
    {text:'躲進旁邊的房間',next:'night_nurse_hide',danger:true,personality:{cautious:+10}},
    {text:'舉起手術刀對抗',next:'night_nurse_fight',danger:true,condition:()=>hasItem('scalpel'),personality:{calm:-10,cautious:-10}}
  ]
};

/* ===== 19. 躲起來 ===== */
