/* ===== 20. 跑 ===== */
SCENES.night_nurse_run={
  room:'走廊',roomName:'逃跑',sceneId:'遭遇',
  text:[
    '<p>你轉身就跑。</p>',
    '<p>你的腳踩在瓷磚地上，「咚咚咚」地響。背後的腳步聲也快了——「噠噠噠噠」——像在你的腦袋裡敲。</p>',
    '<p>你跑得肺在燒。你不知道自己在跑向哪裡。你只知道你不能停下來。</p>',
    '<p>你拐了一個彎。又拐了一個彎。背後的腳步聲——不見了。</p>',
    '<p>你彎著腰，雙手撐膝蓋，大口喘氣。</p>',
    '<p>你發現自己站在二樓樓梯口。</p>',
    '<p class="inherit-note">你甩掉了夜巡護士。但你在慌亂中跑丟了一樣東西——你的物品欄裡少了一樣。</p>'
  ],
  onEnter:()=>{loseTime(5);
    if(Math.random()<0.3){
      setTimeout(()=>goToScene('ending_bad_nightnurse'),1500);
      return;
    }
    state.flags.nurse_escaped=true;
    if(state.inventory.length>0){const lost=state.inventory.pop();removeItem(lost.id);appendNarrative('<p class="system-msg">你在慌亂中掉了「'+lost.name+'」。回頭找太危險了。</p>');}
  },
  choices:[
    {text:'繼續探索二樓',next:'internal_med'},
    {text:'下樓回大廳',next:'entrance'},
    {text:'上三樓',next:'operating_room'}
  ]
};

/* ===== 21. 對抗 ===== */
SCENES.night_nurse_fight={
  room:'走廊',roomName:'對抗',sceneId:'遭遇',mood:'terror',
  text:[
    '<p>你拔出了手術刀。</p>',
    '<p>她看到刀。她停了一下。</p>',
    '<p>然後她繼續走。</p>',
    '<p>[shake]你舉起刀。她撲過來——你差點躲開。她的注射器擦著你的脖子過去。你聞到她身上的味道——消毒水，還有一點點，像鮮花。</p>',
    '<p>你反手一刀——劃在她的手臂上。</p>',
    '<p>但她沒有流血。劃開的地方露出來的——不是皮膚。是一團發光的、像記憶碎片一樣的東西。</p>',
    '<p>她停住了。她低下頭看了看自己的手臂。然後她轉過頭看你。她的純黑眼睛裡，第一次出現了——不是情緒。是困惑。</p>',
    '<p class="dialogue">你……是來救我的嗎？她說。聲音不復是之前那種風吹鑰匙孔的聲音了。是一個年輕女人的聲音。有點沙。有點害怕。</p>',
    '<p>你僵住了。</p>',
    '<p class="dialogue">我……我在這裡很久了。她說。我忘記我是誰了。我只記得我要巡夜。我要給人打針。但我不記得為什麼。</p>',
    '<p>她的手鬆開了。注射器掉在地上。</p>',
    '<p class="inherit-note">你打傷了夜巡護士。她恢復了一點自我意識。她不是怪物——她是一個被困住的人。</p>',
    '<p>她轉過身。慢慢地走進了走廊的黑暗裡。</p>',
    '<p class="action">你站在原地。手還在抖。</p>'
  ],
  onEnter:()=>{state.flags.nurse_defeated=true;damage(15);loseTime(5);},
  choices:[
    {text:'回二樓',next:'second_floor'},
    {text:'回大廳',next:'entrance'},
    {text:'上三樓',next:'operating_room'}
  ]
};

/* ===== 22. 林醫生的故事 ===== */
SCENES.lin_doctor_story={
  room:'1F',roomName:'林醫生',sceneId:'支線',mood:'melancholy',
  text:[
    '<p>你走到林醫生旁邊。他還在轉那支鋼筆。</p>',
    '<p class="dialogue">你重置過三次。你說。</p>',
    '<p class="dialogue">嗯。他說。繼續轉。</p>',
    '<p class="dialogue">每次重置，你都失去什麼？</p>',
    '<p>他停了。鋼筆停在他手指之間。</p>',
    '<p>他看著你。看了很久。</p>',
    '<p class="dialogue">第一次重置，我失去了我女兒的名字。他說。我記得我有過一個女兒。我記得她長得像她媽媽。但我想不起她叫什麼。</p>',
    '<p>他的聲音很平。像在說別人的事。</p>',
    '<p class="dialogue">第二次重置，我失去了我妻子的臉。我記得她是個護士。我記得她笑起來很好看。但我想不起她長什麼樣子了。</p>',
    '<p>他把鋼筆放進口袋。</p>',
    '<p class="dialogue">第三次重置——他停了一下。第三次，我差點忘記我是個醫生。我差點忘記我為什麼要拿著手術刀。我在大廳站了半個小時，不知道自己是誰。</p>',
    '<p>他低下頭。</p>',
    '<p class="dialogue">所以你知道我為什麼來這扇門扉嗎？不是為了通關。是為了找回我的記憶。我記得在某扇門扉裡，我見過一個小女孩。她在叫爸爸。我以為她在叫我。</p>',
    '<p>他抬起頭。眼睛紅了。但他沒有哭。</p>',
    '<p class="dialogue">後來我才知道。她不是叫我。她叫的是她自己的爸爸。</p>',
    '<p class="inherit-note">林醫生重置過三次。他失去了女兒的名字、妻子的臉、還有一半的自己。他不是為了通關而來——他是為了找回記憶。</p>',
    '<p>你沒有說話。你拍了拍他的肩膀。</p>',
    '<p>他點了點頭。</p>',
    '<p class="action">你回到大廳。</p>'
  ],
  onEnter:()=>{state.flags.lin_story_done=true;loseTime(3)},
  choices:[{text:'回到大廳',next:'entrance'}]
};

/* ===== 23. 小雨的故事 ===== */
SCENES.nurse_story={
  room:'1F',roomName:'小雨',sceneId:'支線',
  text:[
    '<p>小雨縮在接待台旁邊。雙手抱著膝蓋。</p>',
    '<p>你走過去。蹲在她旁邊。</p>',
    '<p class="dialogue">你叫王小雨？你問。</p>',
    '<p>她點頭。眼淚在眼眶裡打轉。</p>',
    '<p class="dialogue">我……我只是一個護理系的學生。她說。我昨天還在圖書館背書。今天醒來就在這裡了。</p>',
    '<p>她的聲音在抖。</p>',
    '<p class="dialogue">我不想死在這裡。我媽媽還在等我回家吃晚飯。她做了紅燒肉。我答應她我會回去的。</p>',
    '<p>眼淚掉下來了。她趕緊用手背擦。</p>',
    '<p class="dialogue">對不起。我不應該哭的。林醫生說過，哭沒有用。我知道。但我——</p>',
    '<p>她說不下去了。</p>',
    '<p>你遞給她一瓶水。是你從自動販賣機買的那瓶。</p>',
    '<p>她接過去。喝了一口。</p>',
    '<p class="dialogue">謝謝。她說。她的聲音平靜了一點。</p>',
    '<p class="dialogue">你天生能感受別人的悲傷。你說。</p>',
    '<p class="dialogue">嗯。她說。我能感覺到別人的情緒。很強。我在圖書館的時候——我能感覺到書在難過。你信嗎？</p>',
    '<p>你說你信。</p>',
    '<p class="dialogue">在這裡……她說。在這裡我能感覺到整棟醫院在難過。它在哭。從一樓到五樓，從地下室到屋頂。它在哭。</p>',
    '<p>她抬起頭看著你。</p>',
    '<p class="dialogue">我不想讓它繼續哭了。她說。即使我死在這裡——我想讓它停止。</p>',
    '<p class="inherit-note">小雨敏銳的共情讓她能感覺到整棟醫院的悲傷。她害怕，但她不想逃避。</p>',
    '<p class="action">你拍了拍她的頭。她站起來。擦乾了眼淚。</p>'
  ],
  onEnter:()=>{state.flags.nurse_story_done=true;loseTime(3)},
  choices:[{text:'回到大廳',next:'entrance'}]
};

/* ===== 24. 手術室 ===== */
